insert into public.skills (id, label, balance, why, traits, path_id, class_ids, aliases, trainer_led, sort) values
  ('loose_leash', 'Loose leash', 'physical', 'A loose leash is what makes {dog} easy to bring to a patio.', '{"pulls"}', 'loose-leash-walking', '{"loose-leash","focus-recall"}', '{"Loose leash"}', false, 0),
  ('calm_dogs', 'Calm around dogs', 'social', 'Calm around dogs is what opens group classes and busy sidewalks to {dog}.', '{"nervous_dogs","leash_reactive"}', 'calm-around-dogs', '{"calm-private","parallel-walk","small-group-play"}', '{"Confidence"}', false, 10),
  ('recall', 'Recall', 'mental', 'A come {dog} answers every time is what earns more freedom at the park.', '{"recall"}', null, '{"focus-recall"}', '{"Recall","Stop"}', false, 20),
  ('settle_public', 'Settle in public', 'social', 'Settling in public turns a coffee stop into something {dog} can join.', '{"settle_public"}', null, '{"focus-recall"}', '{"Settle","Focus","Gate wait"}', false, 30),
  ('greetings', 'Polite greetings', 'social', 'Four paws on the floor makes {dog} welcome when friends come over.', '{"jumps"}', null, '{}', '{}', false, 40),
  ('calm_people', 'Calm around people', 'social', 'Calm around people lets {dog} relax when the house or the sidewalk gets busy.', '{"shy_people","barks_visitors"}', null, '{}', '{}', false, 50),
  ('leave_it', 'Leave it', 'mental', 'Leave it keeps {dog} safe around bikes, cars and dropped food.', '{"chases"}', null, '{"focus-recall"}', '{}', false, 60),
  ('play_manners', 'Play manners', 'social', 'Good play manners mean other dogs want to play with {dog}.', '{"rough_play"}', null, '{"small-group-play"}', '{"Play manners"}', false, 70),
  ('sharing', 'Calm around food and toys', 'mental', 'Feeling safe around food and toys makes {dog} easier to live with and to bring places.', '{"guards"}', null, '{}', '{}', true, 80),
  ('alone_time', 'Alone time', 'mental', 'Being fine alone gives {dog} a calmer day, and gives you one too.', '{"alone"}', null, '{}', '{}', true, 90),
  ('settle_home', 'Settle at home', 'mental', 'A dog who can switch off at home rests better and copes better out.', '{"crate"}', null, '{}', '{}', false, 100),
  ('enrichment', 'Enrichment', 'mental', 'Nose and brain work tire {dog} out in a way a walk alone can''t.', '{"bored_chewing"}', null, '{"scent-work","sniff-space"}', '{}', false, 110),
  ('fitness', 'Fitness', 'physical', 'A fit dog stays sound for sport days and is calmer at home.', '{}', null, '{"fitness","agility-drop-in"}', '{}', false, 120),
  ('decompression', 'Decompression', 'mental', 'A slow sniff lets {dog} unwind after a busy day.', '{}', null, '{"sniff-space"}', '{}', false, 130),
  ('drop_it', 'Drop it', 'mental', 'Drop it keeps games going and gets things out of {dog}''s mouth without a chase.', '{}', null, '{}', '{}', false, 140)
insert into public.drills (id, skill_id, title, minutes, setting, level, activity, image, goal, needs, steps, good, stop_if, sort, active) values
  ('turn-and-go', 'loose_leash', 'Turn and go', 15, 'On your walk', 'start', 'walk', 'pulling_on_leash', '{dog} learns pulling takes the walk backwards.', '{"Treats","6 ft leash","A quiet street"}', '{"Walk at your normal pace.","The moment the leash goes tight, turn and walk the other way.","Mark and treat when {dog} catches up beside you.","Repeat for the length of one block."}', '{dog} checks in with you before the leash goes tight.', '{dog} is too wound up to take treats. Head somewhere quieter.', 0, true),
  ('red-light', 'loose_leash', 'Red light, green light', 10, 'On your walk', 'start', 'walk', 'dog_providing_good_eye_contact', 'A tight leash stops the walk; a loose one starts it again.', '{"Treats","6 ft leash"}', '{"Walk forward while the leash is loose.","When it goes tight, stop and stand still.","Wait for any slack, a step back or a look at you.","Say yes and walk on."}', 'The stops get shorter because {dog} comes back on their own.', '{dog} spins or barks at the stops. Go back to Turn and go.', 10, true),
  ('pace-changes', 'loose_leash', 'Pace changes', 15, 'On your walk', 'next', 'walk', 'dog_and_owner_chilling', '{dog} keeps watching you as the walk speeds up and slows down.', '{"Treats","6 ft leash"}', '{"Walk ten steps at a normal pace.","Slow right down for five steps, then speed up for five.","Treat at your side every time {dog} matches your pace.","Mix the order so it stays a game."}', '{dog} adjusts without the leash tightening.', 'The leash is tight more than it is loose. Slow the changes down.', 20, true),
  ('sit-at-corners', 'loose_leash', 'Sit at every corner', 10, 'On your walk', 'next', 'walk', 'dog_being_patient', 'Every curb is a pause, so the walk has a calm rhythm.', '{"Treats","6 ft leash"}', '{"Slow down as you reach the curb.","Ask for a sit and treat it.","Wait two seconds, then say a release word and cross.","Stretch the wait a little each corner."}', '{dog} sits at the curb before you ask.', 'Traffic is too much to think around. Pick a quieter route.', 30, true),
  ('busy-street', 'loose_leash', 'Busy street', 20, 'Downtown', 'harder', 'out', 'dog_chilling_in_car', 'The loose leash holds up with people, smells and noise around.', '{"High-value treats","6 ft leash","A busy block"}', '{"Start at the quiet end of a busy block.","Walk a short stretch and treat often at your side.","Turn and go the moment the leash goes tight.","End on a calm stretch and head home."}', '{dog} looks around, then back at you, and keeps walking.', '{dog} stops taking treats or freezes. Back to a quieter street.', 40, true),
  ('past-a-dog', 'loose_leash', 'Past a calm dog', 20, 'On your walk', 'harder', 'walk', 'dogs_meeting_on_leash', '{dog} walks past another dog on a loose leash.', '{"High-value treats","6 ft leash","A friend with a calm dog"}', '{"Ask your friend to stand still across the street.","Walk past at that distance, treating as {dog} looks.","Cross a little closer on each pass.","Stop after three good passes."}', 'The leash stays loose all the way past.', '{dog} stiffens, stares or lunges. Add distance and end on an easy pass.', 50, true),
  ('watch-the-park', 'calm_dogs', 'Watch the park', 10, 'Outside the dog park', 'start', 'park', 'dog_getting_pets_at_park', '{dog} sees dogs playing and stays calm enough to eat.', '{"Treats","6 ft leash","A spot past the fence"}', '{"Stand far enough from the fence that {dog} notices dogs but can still take food.","Every time {dog} looks at a dog, mark and treat.","Move 5 steps closer only after 5 calm looks in a row.","End while it''s still easy."}', '{dog} looks at a dog, then back at you.', '{dog} stiffens, stares or lunges. Add distance and end on an easy rep.', 60, true),
  ('u-turn', 'calm_dogs', 'Let''s go U-turn', 10, 'On your walk', 'next', 'walk', 'pulling_on_leash', 'An easy way out when a dog appears too close.', '{"Treats","6 ft leash"}', '{"On a quiet street, say \"let''s go\" and turn away with a treat at {dog}''s nose.","Practice it ten times with no dogs around.","On a walk, use it the moment you see a dog before {dog} locks on.","Treat as you walk away."}', '{dog} turns with you as soon as you say it.', 'You''re turning too late to help. Walk at quieter times for now.', 70, true),
  ('parallel-practice', 'calm_dogs', 'Parallel walk practice', 20, 'On your walk', 'harder', 'walk', 'dog_chilling_with_owner_on_porch', '{dog} walks the same way as a calm dog across the street.', '{"Treats","6 ft leash","A friend with a calm dog"}', '{"Walk the same direction on opposite sides of a quiet street.","Treat each time {dog} looks at the other dog and looks away.","If it goes well for a block, close the gap by a few steps.","Finish apart, with both dogs relaxed."}', '{dog} sniffs and walks as if the other dog is just part of the street.', '{dog} stiffens, stares or lunges. Add distance and end on an easy rep.', 80, true),
  ('name-game', 'recall', 'Name game', 5, 'At home', 'start', 'train', 'dog_providing_good_eye_contact', '{dog}''s name means good things happen near you.', '{"Treats"}', '{"Say {dog}''s name once in a happy voice.","The moment {dog} looks at you, mark and treat.","Do it from other rooms and when {dog} is busy.","Ten reps, a few times a day."}', '{dog} turns the instant the name is said.', 'You''re saying the name more than once. Move closer and make it easier.', 90, true),
  ('ping-pong', 'recall', 'Ping-pong recall', 10, 'At home or in the yard', 'next', 'train', 'athletic_dog_catching_ball', '{dog} runs between two people for a reward every time.', '{"Treats","A second person"}', '{"Stand a few steps apart from your helper.","Take turns calling {dog} once.","Treat and touch the collar when {dog} arrives.","Step further apart as it gets easy."}', '{dog} runs straight in, fast, without being called twice.', '{dog} wanders off between calls. Shorten the distance.', 100, true),
  ('long-line', 'recall', 'Long line at the park', 15, 'At the park', 'harder', 'park', 'dog_running_on_beach', 'The come holds up with smells and dogs around.', '{"High-value treats","15 ft long line","A quiet park"}', '{"Let {dog} explore on the long line.","When {dog} isn''t too busy, call once and back away.","Treat well and let {dog} go sniff again.","Five good recalls, then head home."}', '{dog} comes away from a smell on the first call.', 'You need the line to bring {dog} in. Go back to Ping-pong recall.', 110, true),
  ('mat-at-home', 'settle_public', 'Mat at home', 10, 'At home', 'start', 'train', 'dog_sleeping_while_owner_reads', 'A mat that means lie down and relax.', '{"A mat or towel","Treats"}', '{"Put the mat down and treat any paw on it.","Then treat only sits, then only downs on the mat.","Treat calm every few seconds while you read or watch TV.","Pick the mat up when you finish."}', '{dog} lies on the mat as soon as it goes down.', '{dog} is restless. Try after a walk, when {dog} is tired.', 120, true),
  ('patio-settle', 'settle_public', 'Patio settle', 20, 'On a patio', 'next', 'patio', 'dog_chilling_with_owner_on_porch', '{dog} lies down and stays settled while you have a coffee.', '{"A mat or towel","A long chew","Treats"}', '{"Bring a mat or towel and a long chew.","Pick a table at the edge, away from the door.","Reward any down on the mat, then reward calm every 30 seconds.","Leave before {dog} has had enough."}', '{dog} lies on the mat and watches people go by.', '{dog} can''t take food. Try a quieter time.', 130, true),
  ('bench-watch', 'settle_public', 'Bench watching', 15, 'Out and about', 'harder', 'out', 'dog_being_patient', '{dog} settles beside you somewhere busy.', '{"A mat or towel","Treats"}', '{"Sit on a bench near a market or shop entrance.","Treat each calm look at people passing.","Treat a down and then calm every minute.","Stay ten minutes, then leave on a good note."}', '{dog} lies down and dozes off.', '{dog} keeps standing up to watch. Move further from the crowd.', 140, true),
  ('four-on-floor', 'greetings', 'Four on the floor', 5, 'At home', 'start', 'train', 'dog_providing_good_eye_contact', 'Attention comes when all four paws are down.', '{"Treats"}', '{"Walk in the door calmly.","If {dog} jumps, turn away and wait.","Treat on the floor as soon as all four paws land.","Say hello once {dog} stays down."}', '{dog} waits with paws on the floor when you come in.', 'The jumping gets bigger. Keep greetings short and boring.', 150, true),
  ('doorbell-sit', 'greetings', 'Doorbell sit', 10, 'At home', 'next', 'train', 'dog_being_patient', '{dog} sits back from the door when someone arrives.', '{"Treats","A helper to knock"}', '{"Ask a helper to knock.","Toss a treat behind {dog}, away from the door.","Ask for a sit before you open it.","Open only while {dog} stays sitting."}', '{dog} goes to the spot when someone knocks.', '{dog} is barking too hard to listen. Practice with a softer knock.', 160, true),
  ('greet-a-friend', 'greetings', 'Greet a friend', 10, 'On your walk', 'harder', 'walk', 'dog_and_owner_chilling', '{dog} says hi to people with four paws down.', '{"Treats","A friend"}', '{"Ask a friend to walk up slowly.","They stop if {dog} jumps and step back.","They pet {dog} only while {dog} sits or stands calmly.","Three short greetings, then walk on."}', '{dog} sits as the friend comes close.', '{dog} is too excited to sit. Try with a calmer friend or after a walk.', 170, true),
  ('treat-from-afar', 'calm_people', 'Treats from afar', 10, 'On your walk', 'start', 'walk', 'dog_being_patient', 'People passing mean treats, not worry.', '{"Treats","6 ft leash"}', '{"Stand back from a path where people walk by.","Each time someone passes, treat.","Stop the treats when they''re gone.","Move closer only when {dog} looks for the treat."}', '{dog} sees a person and looks at you for the treat.', '{dog} barks, hides or won''t eat. Add distance.', 180, true),
  ('visitor-toss', 'calm_people', 'Visitor toss', 10, 'At home', 'next', 'train', 'dog_sleeping_while_owner_reads', '{dog} learns visitors are safe and can be ignored.', '{"Treats","A calm visitor"}', '{"Ask your visitor to sit and not reach for {dog}.","They toss a treat away from themselves now and then.","Let {dog} choose to come closer, or not.","Keep visits short to start."}', '{dog} sniffs the visitor and walks off relaxed.', '{dog} growls or freezes. Stop and give {dog} space.', 190, true),
  ('busy-door', 'calm_people', 'Shop doorway', 15, 'Out and about', 'harder', 'out', 'dog_chilling_in_car', '{dog} stays relaxed near a busy entrance.', '{"Treats","A mat or towel"}', '{"Stand well back from a shop entrance.","Treat each person who comes out.","Move a few steps closer when {dog} is loose and curious.","Leave after ten minutes."}', '{dog} watches the door with a soft body.', '{dog} pulls away or won''t eat. Go back to Treats from afar.', 200, true),
  ('closed-hand', 'leave_it', 'Closed hand', 5, 'At home', 'start', 'train', 'dog_providing_good_eye_contact', '{dog} backs off from something to get something better.', '{"Treats"}', '{"Hold a treat in a closed hand.","Wait while {dog} sniffs and paws.","The moment {dog} backs off, treat from the other hand.","Add \"leave it\" once it''s easy."}', '{dog} looks at you instead of your hand.', '{dog} gets frustrated. Use a less exciting treat in the hand.', 210, true),
  ('floor-leave', 'leave_it', 'Leave it on the floor', 10, 'At home', 'next', 'train', 'dog_being_patient', '{dog} walks past food on the floor.', '{"Treats","6 ft leash"}', '{"Put a treat on the floor and cover it with your foot.","Say \"leave it\" and treat from your hand when {dog} looks away.","Uncover it a little at a time.","Walk past it on leash and treat at your side."}', '{dog} glances at it and keeps walking.', '{dog} lunges for it. Keep it covered for longer.', 220, true),
  ('bike-watch', 'leave_it', 'Bikes go by', 15, 'Near a bike path', 'harder', 'walk', 'pulling_on_leash', '{dog} watches bikes pass without chasing.', '{"High-value treats","6 ft leash"}', '{"Stand well back from a bike path.","Treat as each bike goes by.","Ask for a look at you before the treat as it gets easy.","Move closer over several visits, not one."}', '{dog} sees a bike and turns to you.', '{dog} lunges or spins. Add distance.', 230, true),
  ('play-pause', 'play_manners', 'Play and pause', 10, 'At home or in the yard', 'start', 'play', 'athletic_dog_catching_ball', '{dog} can calm down in the middle of a game.', '{"A tug toy","Treats"}', '{"Play tug for ten seconds.","Freeze and hold the toy still.","When {dog} lets go and sits, start again.","Five rounds, then end the game."}', '{dog} lets go and sits as soon as you freeze.', '{dog} grabs at hands or clothes. End the game for now.', 240, true),
  ('call-out', 'play_manners', 'Call out of play', 15, 'At the park', 'next', 'park', 'dog_getting_pets_at_park', '{dog} takes breaks during play with another dog.', '{"High-value treats","A friend with a dog {dog} knows"}', '{"Let the dogs play for thirty seconds.","Call {dog} and treat when {dog} comes.","Send {dog} back to play straight away.","Repeat every minute or so."}', '{dog} comes when called and goes back calm.', 'Play gets loud and stiff. Separate them for a break.', 250, true),
  ('calm-buddy', 'play_manners', 'Calm buddy walk', 20, 'On your walk', 'harder', 'walk', 'dogs_meeting_on_leash', '{dog} spends time with another dog without playing rough.', '{"Treats","A friend with a calm dog"}', '{"Walk side by side first.","Let the dogs sniff for three seconds, then move on.","Short sniffs, lots of walking.","End before either dog gets wound up."}', 'Loose bodies and short, polite sniffs.', '{dog} stiffens or mounts. Move apart and keep walking.', 260, true),
  ('trade-up', 'sharing', 'Trade up', 5, 'At home', 'start', 'train', 'dog_and_owner_chilling', 'Your hand near {dog}''s things means something better arrives.', '{"A low-value toy","High-value treats"}', '{"Give {dog} a toy {dog} doesn''t care much about.","Toss a treat near, not at, {dog}.","Walk away. Do not take the toy.","Repeat a few times a day."}', '{dog} looks up happily when you come near.', '{dog} stiffens, freezes or growls. Stop and book a 1:1.', 270, true),
  ('walk-by-bowl', 'sharing', 'Walk past the bowl', 5, 'At home', 'next', 'train', 'dog_being_patient', 'People passing the bowl add food, never take it.', '{"Treats"}', '{"While {dog} eats, walk past at a distance.","Toss a treat toward the bowl as you pass.","Keep walking.","Come a step closer only over many meals."}', '{dog} keeps eating with a loose body as you pass.', '{dog} eats faster, freezes or growls. Stop and book a 1:1.', 280, true),
  ('drop-for-treat', 'sharing', 'Drop for a treat', 5, 'At home', 'harder', 'train', 'dog_providing_good_eye_contact', '{dog} drops a toy because giving it up pays.', '{"A low-value toy","High-value treats"}', '{"Show a treat at {dog}''s nose.","Say \"drop\" as {dog} lets go.","Give the treat, then give the toy back.","Three reps, then end."}', '{dog} drops it and waits for the toy to come back.', '{dog} guards harder. Stop and book a 1:1.', 290, true),
  ('door-in-out', 'alone_time', 'Out the door and back', 5, 'At home', 'start', 'alone', 'dog_sleeping_while_owner_reads', 'You leaving is boring because you always come back.', '{"A long chew"}', '{"Give {dog} a chew.","Step out the door and close it.","Come back in after a few seconds, calmly.","Do it ten times, only as long as {dog} stays relaxed."}', '{dog} keeps chewing as you go out.', '{dog} whines, paces or scratches the door. Make it shorter.', 300, true),
  ('busy-chew', 'alone_time', 'Chew while you''re busy', 15, 'At home', 'next', 'alone', 'dog_wrapped_in_blanket', '{dog} settles in another room while you''re home.', '{"A long chew","A baby gate"}', '{"Set {dog} up with a chew behind a baby gate.","Potter around where {dog} can see you.","Then step out of sight for a minute.","Come back before {dog} finishes the chew."}', '{dog} stays on the chew while you''re out of sight.', '{dog} stops chewing to watch for you. Stay in sight longer.', 310, true),
  ('short-errand', 'alone_time', 'A short errand', 15, 'At home', 'harder', 'alone', 'dog_sleeping_while_owner_reads', '{dog} rests through a short time alone.', '{"A long chew","A camera if you have one"}', '{"Walk {dog} first.","Leave with no fuss and a chew down.","Be back in ten minutes.","Come in calmly and say hi once {dog} settles."}', '{dog} is lying down when you get back.', '{dog} barks or paces the whole time. Go back a step.', 320, true),
  ('crate-games', 'settle_home', 'Crate games', 10, 'At home', 'start', 'train', 'dog_wrapped_in_blanket', 'The crate is where good things show up.', '{"Treats","A crate with the door open"}', '{"Toss a treat into the crate.","Let {dog} go in and come out freely.","Treat inside when {dog} lies down.","Close the door for a few seconds, then open it."}', '{dog} walks in on their own to see what''s there.', '{dog} won''t go in. Toss the treats just at the door.', 330, true),
  ('settle-cue', 'settle_home', 'Settle on cue', 10, 'At home', 'next', 'train', 'dog_sleeping_while_owner_reads', '{dog} lies down and relaxes when you sit down.', '{"A mat or bed","Treats"}', '{"Sit on the couch with {dog} on a leash.","Wait. Treat any calm lie-down.","Treat slow blinks and sighs.","Practice every evening."}', '{dog} flops onto a hip when you sit down.', '{dog} keeps asking to play. Try after exercise.', 340, true),
  ('nap-after-walk', 'settle_home', 'Quiet after a walk', 15, 'At home', 'harder', 'train', 'dog_wrapped_in_blanket', '{dog} learns walks end in rest, not more play.', '{"A long chew","A quiet room"}', '{"Come home from a walk.","Give a chew on the bed straight away.","Keep the room quiet and lights low.","Let {dog} sleep it off."}', '{dog} falls asleep within fifteen minutes.', '{dog} is still wired. Make the walk sniffier next time.', 350, true),
  ('scatter-feed', 'enrichment', 'Scatter feed', 10, 'In the yard or at home', 'start', 'puzzle', 'dog_chilling', '{dog} uses their nose to find dinner.', '{"Dinner kibble"}', '{"Scatter a handful of kibble on grass or a towel.","Let {dog} find every piece.","Make the area bigger as it gets easy.","Use part of a meal so it doesn''t add extra food."}', '{dog} sniffs slowly and keeps searching.', '{dog} gives up quickly. Use a smaller area.', 360, true),
  ('cup-game', 'enrichment', 'Cup game', 10, 'At home', 'next', 'puzzle', 'dog_and_owner_chilling', '{dog} finds the treat under one of three cups.', '{"Three cups","Treats"}', '{"Put a treat under one cup while {dog} watches.","Let {dog} nose the right one and lift it.","Shuffle slowly as it gets easy.","Stop after ten finds."}', '{dog} sniffs each cup and picks the right one.', '{dog} knocks cups over in frustration. Use one cup.', 370, true),
  ('find-it', 'enrichment', 'Find it, room to room', 15, 'At home', 'harder', 'puzzle', 'dog_and_owner_chilling', '{dog} searches the house for a hidden treat or toy.', '{"Treats or a toy"}', '{"Have {dog} wait in one room.","Hide a treat somewhere easy in the next room.","Say \"find it\" and let {dog} search.","Make the hides harder over time."}', '{dog} works the room on their own.', '{dog} keeps looking at you for help. Make the hides easier.', 380, true),
  ('sit-stand', 'fitness', 'Sit to stand', 5, 'At home', 'start', 'train', 'dog_being_patient', 'Builds the back legs with slow, square reps.', '{"Treats","A non-slip floor"}', '{"Ask for a sit, then a stand, then a sit.","Keep it slow and square.","Do five reps.","Rest and do one more set."}', '{dog} stands up straight without shuffling forward.', '{dog} sits to one side or seems sore. Stop and check with your vet.', 390, true),
  ('hill-walk', 'fitness', 'Hill walks', 20, 'On your walk', 'next', 'hike', 'dog_running_on_beach', 'Strength from walking up and down a gentle hill.', '{"6 ft leash","A gentle hill"}', '{"Walk up a gentle slope at a steady pace.","Walk back down slowly.","Repeat three to five times.","Finish with a flat cool-down."}', '{dog} keeps a steady pace up and down.', '{dog} lags or pants hard. Cut it short.', 400, true),
  ('cavaletti', 'fitness', 'Pole walk', 10, 'In the yard', 'harder', 'play', 'athletic_dog_catching_ball', '{dog} lifts each paw cleanly over low poles.', '{"4 broom handles or poles","Treats"}', '{"Lay poles on the ground a stride apart.","Walk {dog} over them slowly on leash.","Treat at the end.","Five passes each way."}', '{dog} steps over each pole without knocking it.', '{dog} trips or rushes. Space the poles wider.', 410, true),
  ('sniffari', 'decompression', 'Sniffari', 30, 'Somewhere green', 'start', 'sniff', 'dog_chilling', '{dog} sets the pace and sniffs as long as they like.', '{"Long leash or harness"}', '{"Pick a quiet green spot.","Let {dog} lead and stop wherever {dog} wants.","Don''t hurry, cue or correct.","Head home when {dog} slows down."}', '{dog} sniffs slowly and comes home relaxed.', 'It''s too busy for {dog} to unwind. Try an earlier time.', 420, true),
  ('new-route', 'decompression', 'A new route', 20, 'On your walk', 'next', 'sniff', 'dog_chilling', 'New smells make a short walk count for more.', '{"6 ft leash"}', '{"Pick a street {dog} hasn''t walked.","Walk slowly and stop at every interesting smell.","Keep it short.","Come home the usual way."}', '{dog} explores with a loose body.', '{dog} is jumpy in the new place. Use a route you know.', 430, true),
  ('lick-mat', 'decompression', 'Lick mat wind-down', 10, 'At home', 'harder', 'puzzle', 'dog_wrapped_in_blanket', 'Licking helps {dog} come down after a busy day.', '{"A lick mat","Wet food or yogurt"}', '{"Spread a thin layer on a lick mat.","Give it in a quiet spot.","Stay nearby and calm.","Pick it up when {dog} is done."}', '{dog} lies down to lick and settles afterwards.', '{dog} chews the mat. Use it only while you''re watching.', 440, true),
  ('two-toys', 'drop_it', 'Two toys', 10, 'At home or in the yard', 'start', 'play', 'athletic_dog_catching_ball', '{dog} drops one toy to get the other.', '{"Two matching toys"}', '{"Throw one toy.","When {dog} brings it back, make the second toy exciting.","Throw the second as soon as the first drops.","Add \"drop\" just before {dog} lets go."}', '{dog} drops the toy at your feet.', '{dog} runs off with the toy. Use a long line.', 450, true),
  ('trade-tug', 'drop_it', 'Tug and trade', 10, 'At home', 'next', 'play', 'athletic_dog_catching_ball', '{dog} lets go of a tug toy on cue.', '{"A tug toy","Treats"}', '{"Play tug for a few seconds.","Stop moving and say \"drop\".","Treat when {dog} lets go, then restart tug.","Ten reps."}', '{dog} lets go as soon as the toy goes still.', '{dog} won''t let go. Hold the treat at the nose first.', 460, true),
  ('drop-outside', 'drop_it', 'Drop it on a walk', 10, 'On your walk', 'harder', 'walk', 'pulling_on_leash', '{dog} drops a stick or bit of trash when asked.', '{"High-value treats","6 ft leash"}', '{"Carry great treats.","When {dog} picks something up, say \"drop\" once.","Treat on the ground away from the item.","Pick it up while {dog} eats."}', '{dog} drops it before you reach for it.', 'It''s something dangerous. Swap for a treat right away and practice at home.', 470, true)
